using System.Text.Json;
using Xunit;

namespace CapabilityExplorer.Tests;

/// <summary>Locates the repository's fixtures. Golden artifacts and fixture repos are inputs, never generated by tests.</summary>
public static class Fixtures
{
    public static string RepositoryRoot { get; } = FindRoot();

    public static string ExpectedDirectory => Path.Combine(RepositoryRoot, "fixtures", "expected");

    /// <summary>Built by scripts/build-fixtures.sh; tests fail loudly rather than skip when it is missing.</summary>
    public static string RepoDirectory(string repositoryId)
    {
        var dir = Path.Combine(RepositoryRoot, "fixtures", ".repos", repositoryId);
        return Directory.Exists(Path.Combine(dir, ".git"))
            ? dir
            : throw new InvalidOperationException($"fixture repo {dir} missing: run `make fixtures` first");
    }

    /// <summary>Relative paths like "api-cs/v1-base/Sales.Api.jsonl".</summary>
    public static IReadOnlyList<string> GoldenFiles { get; } = Directory
        .EnumerateFiles(ExpectedDirectory, "*.jsonl", SearchOption.AllDirectories)
        .Select(f => Path.GetRelativePath(ExpectedDirectory, f).Replace('\\', '/'))
        .Order(StringComparer.Ordinal)
        .ToList();

    public static string Golden(string relativePath) => File.ReadAllText(Path.Combine(ExpectedDirectory, relativePath));

    public static IReadOnlyDictionary<string, IReadOnlyDictionary<string, string>> Lock { get; } =
        JsonSerializer.Deserialize<Dictionary<string, Dictionary<string, string>>>(
                File.ReadAllText(Path.Combine(RepositoryRoot, "fixtures", "revisions.lock.json")))!
            .ToDictionary(kv => kv.Key, kv => (IReadOnlyDictionary<string, string>)kv.Value);

    public static TheoryData<string> GoldenFileData()
    {
        var data = new TheoryData<string>();
        foreach (var f in GoldenFiles)
        {
            data.Add(f);
        }

        return data;
    }

    private static string FindRoot()
    {
        for (var dir = new DirectoryInfo(AppContext.BaseDirectory); dir is not null; dir = dir.Parent)
        {
            if (File.Exists(Path.Combine(dir.FullName, "schema", "v1", "record.schema.json")))
            {
                return dir.FullName;
            }
        }

        throw new InvalidOperationException("repository root (schema/v1/record.schema.json) not found above " + AppContext.BaseDirectory);
    }
}
